// Tuning constants for Cobalt Vault: one place for the sizes, speeds and detection numbers every
// other module reads, so the feel of the heist is balanced here and nowhere else.

/** Internal render size in pixels; the canvas letterboxes this into the window. */
export const VIEW_W = 1280;
export const VIEW_H = 800;

/** Tile grid: every level is this many tiles of TILE pixels. */
export const COLS = 32;
export const ROWS = 20;
export const TILE = 40;

/** The thief, in pixels. */
export const THIEF = {
  radius: 11,
  walkSpeed: 150,   // px/s standing
  sneakSpeed: 78,   // px/s sneaking — slow but silent and hard to spot
  sprintSpeed: 210, // px/s sprinting — loud, and sprint noise wakes nearby guards
};

/**
 * Detection numbers. A guard or camera whose cone holds the thief adds `fillPerSecond` to the
 * shared alarm each second (more the closer the cone's apex is, times the visibility factor);
 * out of sight the alarm cools at `coolPerSecond`. At 1 the heist is blown.
 */
export const DETECTION = {
  fillPerSecond: 0.45,
  closeBonus: 0.35,     // extra fill when the watcher is under 90 px away
  closeRange: 90,
  coolPerSecond: 0.22,
  shadowFactor: 0.12,   // how visible a sneaking thief inside a shadow patch is
  sneakFactor: 0.45,    // how visible a sneaking thief in the open is
  caughtAt: 1.0,
};

/** Sprinting emits a noise ring of this radius that wakes guards it reaches. */
export const NOISE_RADIUS = 190;

/** How long a guard stays alarmed and hunting after losing the thief, in seconds. */
export const HUNT_SECONDS = 5.5;

/** Loot: each gem is one piece of loot; the vault door holds the prize trove. */
export const GEM_VALUE = 1;
export const VAULT_VALUE = 3;
export const VAULT_OPEN_SECONDS = 2.4; // time standing at the vault to crack it

/** Score. */
export const SCORE_GEM = 500;
export const SCORE_VAULT = 2000;
export const SCORE_LEVEL_CLEAR = 1500;
export const SCORE_ALARM_PENALTY = 400; // per alarm trigger, once each
export const PAR_SECONDS = 90;          // finish faster than this for the time bonus

// World state and simulation step for Cobalt Vault: builds a level from its map string, owns
// every entity (thief, guards, cameras, gems, vault, exit) and advances the heist one fixed
// step at a time — movement, patrol, vision, alarm and scoring all live behind world.step().

import { COLS, ROWS, TILE, THIEF, DETECTION, NOISE_RADIUS, HUNT_SECONDS, VAULT_OPEN_SECONDS,
         GEM_VALUE, VAULT_VALUE, SCORE_GEM, SCORE_VAULT, SCORE_LEVEL_CLEAR, SCORE_ALARM_PENALTY } from './config.js';
import { LEVELS } from './levels.js';
import { guardStep } from './guards.js';
import { cameraStep } from './cameras.js';
import { thiefStep } from './player.js';
import { coneSees } from './vision.js';

export const PHASE_TITLE = 'title';
export const PHASE_PLAY = 'play';
export const PHASE_CAUGHT = 'caught';
export const PHASE_CLEAR = 'clear';
export const PHASE_WIN = 'win';

const STEP = 1 / 60;
export { STEP };

export class World {
  constructor() {
    this.reset();
  }

  /** Rebuild everything for `levelIndex` (wrapping after the last floor) with score carried over. */
  reset(levelIndex = 0, carriedScore = 0) {
    this.levelIndex = levelIndex;
    this.score = carriedScore;
    this.phase = PHASE_TITLE;
    this.phaseTimer = 0;
    this.seconds = 0;
    this.alarm = 0;              // shared alarm meter, 0..1
    this.alarmsTriggered = 0;    // how many times the heist was blown (score penalty)
    this.vaultProgress = 0;      // seconds of cracking done on the vault door
    this.statusLine = 'Sneak in. Take everything. Leave quietly.';
    this.buildLevel(levelIndex);
  }

  buildLevel(index) {
    const def = LEVELS[index % LEVELS.length];
    this.levelName = def.name;
    this.solids = [];   // solid[gy][gx] true where a wall or crate blocks sight and movement
    this.crateAt = [];  // crate flag, drawn differently from walls
    this.shadows = [];
    this.gems = [];
    this.vault = null;
    this.exit = null;
    this.spawn = { x: 0, y: 0 };
    for (let gy = 0; gy < ROWS; gy += 1) {
      this.solids[gy] = [];
      this.crateAt[gy] = [];
      for (let gx = 0; gx < COLS; gx += 1) {
        const ch = def.map[gy][gx];
        const wall = ch === '#';
        const crate = ch === 'c';
        this.solids[gy][gx] = wall || crate;
        this.crateAt[gy][gx] = crate;
        const cx = gx * TILE + TILE / 2;
        const cy = gy * TILE + TILE / 2;
        if (ch === 'S') this.spawn = { x: cx, y: cy };
        if (ch === 'E') this.exit = { gx, gy, x: cx, y: cy };
        if (ch === 'g') this.gems.push({ gx, gy, x: cx, y: cy, taken: false });
        if (ch === 'V') this.vault = { gx, gy, x: cx, y: cy, cracked: false };
        if (ch === 's') this.shadows.push({ gx, gy, x: gx * TILE, y: gy * TILE });
      }
    }
    this.guards = def.guards.map((g, i) => ({
      id: i,
      route: g.route.map(([gx, gy]) => ({ x: gx * TILE + TILE / 2, y: gy * TILE + TILE / 2 })),
      speed: g.speed,
      waypoint: 1,
      x: g.route[0][0] * TILE + TILE / 2,
      y: g.route[0][1] * TILE + TILE / 2,
      facing: 0,          // radians the guard looks
      huntTimer: 0,       // >0 means alarmed and hunting the last seen spot
      lastSeen: null,
      fill: 0,            // this guard's personal suspicion share of the alarm
    }));
    this.cameras = def.cameras.map((c, i) => ({
      id: i,
      x: c.tile[0] * TILE + TILE / 2,
      y: c.tile[1] * TILE + TILE / 2,
      from: (c.sweepFrom * Math.PI) / 180,
      to: (c.sweepTo * Math.PI) / 180,
      seconds: c.seconds,
      t: (i * 0.37) % 1,          // de-phase the sweeps
      facing: 0,
    }));
    this.thief = {
      x: this.spawn.x, y: this.spawn.y,
      facing: -Math.PI / 2,
      sneaking: false, sprinting: false,
      noisePulse: 0,   // seconds left of the expanding sprint-noise ring
      moving: false,
    };
    this.lootTotal = this.gems.length + (this.vault ? VAULT_VALUE : 0);
    this.lootTaken = 0;
    this.vaultOccupied = false;
  }

  /** Is the pixel point p inside a shadow patch? */
  inShadow(x, y) {
    return this.shadows.some((s) => x >= s.x && x < s.x + TILE && y >= s.y && y < s.y + TILE);
  }

  /**
   * How visible the thief is right now, 0..1: full in the open, dimmed sneaking, and all but
   * gone when sneaking inside a shadow patch.
   */
  thiefVisibility() {
    const t = this.thief;
    if (t.sneaking && this.inShadow(t.x, t.y)) return DETECTION.shadowFactor;
    if (t.sneaking) return DETECTION.sneakFactor;
    if (this.inShadow(t.x, t.y)) return 0.35;
    return 1;
  }

  /** Advance the whole heist by one fixed step. `input` is the player intent from input.js. */
  step(input) {
    this.phaseTimer += STEP;
    if (this.phase !== PHASE_PLAY) {
      if (this.phase === PHASE_CAUGHT && this.phaseTimer > 2.2) this.retry();
      if (this.phase === PHASE_CLEAR && this.phaseTimer > 2.0) this.nextLevel();
      return;
    }
    this.seconds += STEP;
    thiefStep(this, input);
    for (const guard of this.guards) guardStep(this, guard, STEP);
    for (const camera of this.cameras) cameraStep(this, camera, STEP);
    this.collectLoot();
    this.updateAlarm(STEP);
    if (this.lootTaken >= this.lootTotal && this.atExit()) this.clearLevel();
  }

  /** Pick up gems the thief touches and track vault cracking while E is held beside it. */
  collectLoot() {
    const t = this.thief;
    for (const gem of this.gems) {
      if (gem.taken) continue;
      if (Math.hypot(gem.x - t.x, gem.y - t.y) < TILE * 0.6) {
        gem.taken = true;
        this.lootTaken += GEM_VALUE;
        this.score += SCORE_GEM;
        this.statusLine = 'Gem pocketed.';
      }
    }
    this.vaultOccupied = false;
    if (this.vault && !this.vault.cracked) {
      const near = Math.hypot(this.vault.x - t.x, this.vault.y - t.y) < TILE * 1.1;
      this.vaultOccupied = near;
      if (near && t.cracking) {
        this.vaultProgress += STEP;
        if (this.vaultProgress >= VAULT_OPEN_SECONDS) {
          this.vault.cracked = true;
          this.lootTaken += VAULT_VALUE;
          this.score += SCORE_VAULT;
          this.statusLine = 'Vault cracked — the prize trove is yours!';
        }
      }
    }
  }

  /** Alarm fill from every watcher that can see the thief, and the cool-down when nobody can. */
  updateAlarm(dt) {
    let seen = 0;
    const visibility = this.thiefVisibility();
    for (const guard of this.guards) guard.fill = 0;
    for (const guard of this.guards) {
      if (coneSees(this, guard, this.thief, 0.60, 250) && visibility > 0) {
        const close = Math.hypot(guard.x - this.thief.x, guard.y - this.thief.y) < DETECTION.closeRange;
        seen += DETECTION.fillPerSecond * visibility * (close ? 1 + DETECTION.closeBonus : 1);
        guard.fill = 1;
        guard.huntTimer = HUNT_SECONDS;
        guard.lastSeen = { x: this.thief.x, y: this.thief.y };
      }
    }
    for (const camera of this.cameras) {
      if (coneSees(this, camera, this.thief, 0.46, 210) && visibility > 0) {
        seen += DETECTION.fillPerSecond * 0.7 * visibility;
      }
    }
    if (seen > 0) this.alarm = Math.min(1, this.alarm + seen * dt);
    else this.alarm = Math.max(0, this.alarm - DETECTION.coolPerSecond * dt);
    if (this.alarm >= DETECTION.caughtAt) this.caught('The alarm is screaming. Security has you.');
    for (const guard of this.guards) {
      if (Math.hypot(guard.x - this.thief.x, guard.y - this.thief.y) < 26) {
        this.caught('A guard grabbed you.');
        return;
      }
    }
  }

  /** Sprint noise: emitted by player.js, here it simply wakes guards it reaches. */
  emitNoise(x, y) {
    this.noise = { x, y, radius: NOISE_RADIUS, t: 0.7 };
    for (const guard of this.guards) {
      if (Math.hypot(guard.x - x, guard.y - y) < NOISE_RADIUS) {
        guard.huntTimer = Math.max(guard.huntTimer, HUNT_SECONDS * 0.7);
        guard.lastSeen = { x, y };
      }
    }
  }

  atExit() {
    const e = this.exit;
    return e && Math.hypot(e.x - this.thief.x, e.y - this.thief.y) < TILE * 0.8;
  }

  caught(reason) {
    this.alarmsTriggered += 1;
    this.statusLine = reason;
    this.phase = PHASE_CAUGHT;
    this.phaseTimer = 0;
  }

  /** Retry the same floor, keeping the score but paying the alarm penalty once per blow. */
  retry() {
    const penalty = SCORE_ALARM_PENALTY * this.alarmsTriggered;
    const carried = Math.max(0, this.score - penalty);
    const floor = this.levelIndex;
    this.reset(floor, carried);
    this.alarmsTriggered = 0;
    this.phase = PHASE_PLAY;
    this.statusLine = 'Back in. Quieter this time.';
  }

  clearLevel() {
    this.score += SCORE_LEVEL_CLEAR;
    this.phase = PHASE_CLEAR;
    this.phaseTimer = 0;
  }

  nextLevel() {
    const next = this.levelIndex + 1;
    if (next >= LEVELS.length) {
      this.phase = PHASE_WIN;
      this.phaseTimer = 0;
    } else {
      const score = this.score;
      this.reset(next, score);
      this.phase = PHASE_PLAY;
      this.statusLine = 'Floor cleared. Keep the noise down.';
    }
  }
}

// Line-of-sight and vision-cone math shared by guards and cameras: a cone is a facing, a
// half-angle and a range; seeing means the target sits inside all three and a raycast against
// the level's solids reaches it. Rays step tile by tile (DDA-ish), so crates and walls block.

import { TILE, COLS, ROWS } from './config.js';

/** Is the grid cell solid? Out-of-bounds counts as solid so rays never leave the map. */
function solidAt(world, gx, gy) {
  if (gx < 0 || gy < 0 || gx >= COLS || gy >= ROWS) return true;
  return world.solids[gy][gx];
}

/** Does a straight ray from (x0,y0) to (x1,y1) stay clear of solids? Sampled every 6 px. */
export function lineClear(world, x0, y0, x1, y1) {
  const dx = x1 - x0;
  const dy = y1 - y0;
  const dist = Math.hypot(dx, dy);
  const steps = Math.max(1, Math.ceil(dist / 6));
  for (let i = 1; i <= steps; i += 1) {
    const t = i / steps;
    const x = x0 + dx * t;
    const y = y0 + dy * t;
    if (solidAt(world, Math.floor(x / TILE), Math.floor(y / TILE))) return false;
  }
  return true;
}

/**
 * Does `watcher` (x, y, facing radians) see `target`? The cone opens `halfAngle` radians each
 * side of facing and reaches `range` px; walls and crates block the view.
 */
export function coneSees(world, watcher, target, halfAngle, range) {
  const dx = target.x - watcher.x;
  const dy = target.y - watcher.y;
  const dist = Math.hypot(dx, dy);
  if (dist > range) return false;
  const angle = Math.atan2(dy, dx);
  let diff = Math.abs(angle - watcher.facing);
  while (diff > Math.PI) diff = Math.abs(diff - 2 * Math.PI);
  if (diff > halfAngle) return false;
  return lineClear(world, watcher.x, watcher.y, target.x, target.y);
}

/**
 * The outline of a watcher's cone as [x, y] points — apex first, then the arc — for rendering.
 * Rays are cast every `rays` degrees so the cone visibly hugs cover.
 */
export function coneOutline(world, x, y, facing, halfAngle, range, rayStepDeg = 6) {
  const points = [[x, y]];
  const rays = Math.max(2, Math.ceil((halfAngle * 2 * 180) / Math.PI / rayStepDeg));
  for (let i = 0; i <= rays; i += 1) {
    const a = facing - halfAngle + (2 * halfAngle * i) / rays;
    const cx = Math.cos(a);
    const cy = Math.sin(a);
    let reach = range;
    for (let d = 8; d <= range; d += 8) {
      const px = x + cx * d;
      const py = y + cy * d;
      if (solidAt(world, Math.floor(px / TILE), Math.floor(py / TILE))) {
        reach = d - 4;
        break;
      }
    }
    points.push([x + cx * reach, y + cy * reach]);
  }
  return points;
}

// Guard behaviour: walk the patrol route waypoint to waypoint, turn the cone smoothly toward
// the direction of travel, and when suspicious (noise or a sighting) break off and hunt the
// last seen spot before resuming the patrol at the nearest waypoint.

import { TILE, HUNT_SECONDS } from './config.js';

const GUARD_HALF_ANGLE = 0.60; // radians each side — the cone the player must read
export { GUARD_HALF_ANGLE };


/** Shortest-path-free resume: continue from the route point nearest the guard. */
function nearestWaypoint(guard) {
  let best = 0;
  let bestDist = Infinity;
  guard.route.forEach((p, i) => {
    const d = Math.hypot(p.x - guard.x, p.y - guard.y);
    if (d < bestDist) { bestDist = d; best = i; }
  });
  return best;
}

/** Turn `facing` toward `target` by at most `maxTurn` radians (shortest way around). */
function turnToward(guard, target, maxTurn) {
  const want = Math.atan2(target.y - guard.y, target.x - guard.x);
  let diff = want - guard.facing;
  while (diff > Math.PI) diff -= 2 * Math.PI;
  while (diff < -Math.PI) diff += 2 * Math.PI;
  guard.facing += Math.max(-maxTurn, Math.min(maxTurn, diff));
}

export function guardStep(world, guard, dt) {
  // Hunting: move to the last seen spot while the hunt timer runs, scanning as you go.
  if (guard.huntTimer > 0) {
    guard.huntTimer -= dt;
    const target = guard.lastSeen ?? guard.route[guard.waypoint];
    const dx = target.x - guard.x;
    const dy = target.y - guard.y;
    const dist = Math.hypot(dx, dy);
    turnToward(guard, target, 3.2 * dt);
    if (dist > 4) {
      const speed = guard.speed * 1.5;
      guard.x += (dx / dist) * speed * dt;
      guard.y += (dy / dist) * speed * dt;
    }
    if (dist <= 6 || guard.huntTimer <= 0) {
      guard.huntTimer = 0;
      guard.waypoint = nearestWaypoint(guard);
    }
    return;
  }

  // Patrol: head for the current waypoint, then take the next one around the loop.
  const target = guard.route[guard.waypoint];
  const dx = target.x - guard.x;
  const dy = target.y - guard.y;
  const dist = Math.hypot(dx, dy);
  turnToward(guard, target, 2.6 * dt);
  if (dist > 1) {
    const step = Math.min(guard.speed * dt, dist);
    guard.x += (dx / dist) * step;
    guard.y += (dy / dist) * step;
  } else {
    guard.waypoint = (guard.waypoint + 1) % guard.route.length;
  }
}

// Security cameras: wall-mounted, they sweep their cone steadily between two angles and feed
// the shared alarm whenever the thief is caught in the beam. Cameras never hunt — they only
// watch — so the counter-play is timing the sweep.

export const CAMERA_HALF_ANGLE = 0.46; // radians each side

export function cameraStep(world, camera, dt) {
  // t rides 0..1 and ping-pongs, easing the sweep so the beam visibly slows at each end.
  const period = camera.seconds;
  camera.t = (camera.t + dt / period) % 2;
  const p = camera.t < 1 ? camera.t : 2 - camera.t;
  const eased = p * p * (3 - 2 * p); // smoothstep
  camera.facing = camera.from + (camera.to - camera.from) * eased;
}

// The thief: keyboard-driven movement with three gears — sneak, walk, sprint — circle-vs-grid
// collision against walls and crates, and the sprint noise ring that wakes nearby guards.

import { TILE, THIEF, NOISE_RADIUS } from './config.js';

const NOISE_COOLDOWN = 1.4; // seconds between sprint noise pings

/** Move a circle of `radius` along one axis, stopping at any solid tile it would overlap. */
function moveAxis(world, thief, dx, dy, radius) {
  let x = thief.x + dx;
  let y = thief.y + dy;
  const gx0 = Math.floor((x - radius) / TILE);
  const gx1 = Math.floor((x + radius) / TILE);
  const gy0 = Math.floor((y - radius) / TILE);
  const gy1 = Math.floor((y + radius) / TILE);
  for (let gy = gy0; gy <= gy1; gy += 1) {
    for (let gx = gx0; gx <= gx1; gx += 1) {
      const solid = gx < 0 || gy < 0 || !world.solids[gy] || world.solids[gy][gx];
      if (!solid) continue;
      // Push the circle out of this tile along the axis just moved.
      if (dx > 0) x = Math.min(x, gx * TILE - radius);
      if (dx < 0) x = Math.max(x, (gx + 1) * TILE + radius);
      if (dy > 0) y = Math.min(y, gy * TILE - radius);
      if (dy < 0) y = Math.max(y, (gy + 1) * TILE + radius);
    }
  }
  thief.x = x;
  thief.y = y;
}

export function thiefStep(world, input) {
  const t = world.thief;
  t.sneaking = input.sneak && !input.sprint;
  t.sprinting = input.sprint && !t.sneaking;
  const speed = t.sneaking ? THIEF.sneakSpeed : t.sprinting ? THIEF.sprintSpeed : THIEF.walkSpeed;
  let ax = (input.right ? 1 : 0) - (input.left ? 1 : 0);
  let ay = (input.down ? 1 : 0) - (input.up ? 1 : 0);
  const len = Math.hypot(ax, ay);
  t.moving = len > 0;
  if (len > 0) {
    ax /= len; ay /= len;
    t.facing = Math.atan2(ay, ax);
    moveAxis(world, t, ax * speed / 60, 0, THIEF.radius);
    moveAxis(world, t, 0, ay * speed / 60, THIEF.radius);
  }
  t.cracking = input.interact;

  // Sprinting is loud: ping a noise ring on a cooldown so guards read the rhythm of your steps.
  t.noiseCooldown = Math.max(0, (t.noiseCooldown ?? 0) - 1 / 60);
  if (t.sprinting && t.moving && t.noiseCooldown <= 0) {
    world.emitNoise(t.x, t.y);
    t.noiseCooldown = NOISE_COOLDOWN;
  }
  if (world.noise) {
    world.noise.t -= 1 / 60;
    if (world.noise.t <= 0 || Math.hypot(world.noise.x - t.x, world.noise.y - t.y) > NOISE_RADIUS * 2) {
      world.noise = null;
    }
  }
}

// Keyboard input: the key set a heist needs — WASD or arrows to move, Shift to sneak, Ctrl to
// sprint, E (held) to crack the vault — held as a plain intent object world.step() consumes.

export const KEYS = {
  up: ['KeyW', 'ArrowUp'],
  down: ['KeyS', 'ArrowDown'],
  left: ['KeyA', 'ArrowLeft'],
  right: ['KeyD', 'ArrowRight'],
  sneak: ['ShiftLeft', 'ShiftRight'],
  sprint: ['ControlLeft', 'ControlRight'],
  interact: ['KeyE', 'Space'],
  restart: ['KeyR'],
  start: ['Enter', 'Space'],
};

export class Input {
  constructor() {
    this.down = new Set();
    this.intent = { up: false, down: false, left: false, right: false,
                    sneak: false, sprint: false, interact: false, restart: false };
    window.addEventListener('keydown', (e) => {
      if (KEYS.start.includes(e.code) || KEYS.interact.includes(e.code)) e.preventDefault();
      this.down.add(e.code);
    });
    window.addEventListener('keyup', (e) => this.down.delete(e.code));
    window.addEventListener('blur', () => this.down.clear());
  }

  /** Snapshot the held keys into a fresh intent object for one simulation step. */
  poll() {
    const held = (codes) => codes.some((c) => this.down.has(c));
    const i = this.intent;
    i.up = held(KEYS.up); i.down = held(KEYS.down);
    i.left = held(KEYS.left); i.right = held(KEYS.right);
    i.sneak = held(KEYS.sneak); i.sprint = held(KEYS.sprint);
    i.interact = held(KEYS.interact);
    i.restart = this.down.has('KeyR') && !this.rLatch;
    this.rLatch = this.down.has('KeyR');
    return i;
  }
}

// Original sound, synthesized with Web Audio — no files, no samples: a soft tick when loot is
// taken, a rising two-tone sting when the vault cracks, a sharp alarm klaxon when caught, and
// a low whoosh for the sprint noise ping. All tones are this entry's own.

export class Sfx {
  constructor() {
    /** @type {AudioContext} */
    this.ctx = null;
    this.muted = false;
  }

  /** The context is created on first use: browsers only allow audio after a user gesture. */
  ac() {
    if (!this.ctx) this.ctx = new (window.AudioContext ?? window.webkitAudioContext)();
    if (this.ctx.state === 'suspended') this.ctx.resume();
    return this.ctx;
  }

  /** One enveloped oscillator tone. */
  tone(freq, seconds, type = 'sine', gain = 0.12, when = 0) {
    if (this.muted) return;
    const ac = this.ac();
    const t0 = ac.currentTime + when;
    const osc = ac.createOscillator();
    const env = ac.createGain();
    osc.type = type;
    osc.frequency.setValueAtTime(freq, t0);
    env.gain.setValueAtTime(0, t0);
    env.gain.linearRampToValueAtTime(gain, t0 + 0.015);
    env.gain.exponentialRampToValueAtTime(0.0001, t0 + seconds);
    osc.connect(env).connect(ac.destination);
    osc.start(t0);
    osc.stop(t0 + seconds + 0.05);
  }

  gem() { this.tone(880, 0.12, 'triangle'); this.tone(1320, 0.16, 'triangle', 0.08, 0.07); }
  vault() { this.tone(220, 0.5, 'square', 0.06); this.tone(440, 0.5, 'square', 0.05, 0.18); this.tone(660, 0.7, 'triangle', 0.1, 0.36); }
  alarm() {
    for (let i = 0; i < 3; i += 1) {
      this.tone(740, 0.22, 'sawtooth', 0.1, i * 0.3);
      this.tone(520, 0.22, 'sawtooth', 0.1, i * 0.3 + 0.14);
    }
  }
  noise() { this.tone(140, 0.25, 'sine', 0.08); }
  clear() { [523, 659, 784, 1047].forEach((f, i) => this.tone(f, 0.3, 'triangle', 0.1, i * 0.12)); }
}

// The HUD drawn over the room: objective line and loot tally, the alarm meter that fills red
// as watchers see you, the run timer and score, sneak/sprint gear, and the vault-cracking
// progress bar while E is held. Everything a player reads without leaving the frame.

import { VIEW_W, VIEW_H } from './config.js';
import { VAULT_OPEN_SECONDS } from './config.js';

const HUD_H = 64;

export function drawHud(ctx, world) {
  ctx.save();
  // Top strip.
  ctx.fillStyle = 'rgba(7, 10, 18, 0.85)';
  ctx.fillRect(0, 0, VIEW_W, HUD_H);
  ctx.strokeStyle = 'rgba(90, 140, 200, 0.35)';
  ctx.beginPath();
  ctx.moveTo(0, HUD_H - 1);
  ctx.lineTo(VIEW_W, HUD_H - 1);
  ctx.stroke();

  // Objective + loot tally (left).
  ctx.fillStyle = '#9fc4e8';
  ctx.font = '15px system-ui, sans-serif';
  ctx.textAlign = 'left';
  ctx.fillText(world.levelName, 16, 24);
  const loot = `Loot ${world.lootTaken}/${world.lootTotal}`;
  ctx.fillStyle = world.lootTaken >= world.lootTotal ? '#ffd75e' : '#e8ecf2';
  ctx.font = 'bold 17px system-ui, sans-serif';
  ctx.fillText(loot, 16, 48);
  ctx.font = '13px system-ui, sans-serif';
  ctx.fillStyle = '#7f92a8';
  ctx.fillText(
    world.lootTaken >= world.lootTotal ? 'OBJECTIVE: reach the glowing EXIT' : 'OBJECTIVE: take all loot, stay unseen',
    130, 48);

  // Alarm meter (centre): the meter that decides the heist.
  const meterW = 300;
  const meterX = (VIEW_W - meterW) / 2;
  ctx.fillStyle = '#e8ecf2';
  ctx.font = 'bold 13px system-ui, sans-serif';
  ctx.textAlign = 'center';
  ctx.fillText('ALARM', VIEW_W / 2, 24);
  ctx.fillStyle = 'rgba(0,0,0,0.55)';
  ctx.fillRect(meterX, 32, meterW, 18);
  const hot = world.alarm > 0.6;
  const grad = ctx.createLinearGradient(meterX, 0, meterX + meterW, 0);
  grad.addColorStop(0, '#4cc9f0');
  grad.addColorStop(0.6, '#f4a53c');
  grad.addColorStop(1, '#e8484d');
  ctx.fillStyle = hot ? '#e8484d' : grad;
  ctx.fillRect(meterX, 32, meterW * Math.max(world.alarm, 0.015), 18);
  ctx.strokeStyle = 'rgba(160,190,220,0.5)';
  ctx.strokeRect(meterX + 0.5, 32.5, meterW - 1, 17);
  if (hot) {
    ctx.fillStyle = `rgba(232,72,77,${0.5 + 0.4 * Math.sin(world.seconds * 18)})`;
    ctx.font = 'bold 12px system-ui, sans-serif';
    ctx.fillText('SPOTTED — BREAK LINE OF SIGHT', VIEW_W / 2, 62);
  }

  // Timer and score (right).
  ctx.textAlign = 'right';
  ctx.fillStyle = '#e8ecf2';
  ctx.font = 'bold 16px system-ui, sans-serif';
  const m = Math.floor(world.seconds / 60);
  const s = Math.floor(world.seconds % 60);
  ctx.fillText(`${m}:${String(s).padStart(2, '0')}`, VIEW_W - 130, 28);
  ctx.fillText(`SCORE ${world.score}`, VIEW_W - 130, 50);
  // Gear indicator.
  const gear = world.thief.sneaking ? 'SNEAK' : world.thief.sprinting ? 'SPRINT' : 'WALK';
  ctx.fillStyle = world.thief.sneaking ? '#8fd3ff' : world.thief.sprinting ? '#f4a53c' : '#7f92a8';
  ctx.font = 'bold 13px system-ui, sans-serif';
  ctx.fillText(gear, VIEW_W - 18, 28);
  ctx.fillStyle = '#66788e';
  ctx.font = '12px system-ui, sans-serif';
  ctx.fillText('R restart', VIEW_W - 18, 50);

  // Vault cracking bar.
  if (world.vaultOccupied && world.vault && !world.vault.cracked) {
    const w = 260;
    const x = (VIEW_W - w) / 2;
    const y = VIEW_H - 56;
    ctx.fillStyle = 'rgba(7,10,18,0.85)';
    ctx.fillRect(x - 12, y - 24, w + 24, 44);
    ctx.fillStyle = '#ffd75e';
    ctx.font = 'bold 14px system-ui, sans-serif';
    ctx.textAlign = 'center';
    ctx.fillText('CRACKING VAULT — hold E', VIEW_W / 2, y - 6);
    ctx.fillStyle = 'rgba(0,0,0,0.6)';
    ctx.fillRect(x, y, w, 10);
    ctx.fillStyle = '#ffd75e';
    ctx.fillRect(x, y, w * Math.min(1, world.vaultProgress / VAULT_OPEN_SECONDS), 10);
  }
  ctx.restore();
}

// The renderer: draws the whole heist frame — floor and shadow patches, walls and crates,
// gems and the vault, the exit glow, guards with their raycast vision cones (amber on patrol,
// red on the hunt), sweeping camera cones, the sprint noise ring, the thief, then the HUD and
// the title/caught/cleared/won overlays.

import { VIEW_W, VIEW_H, TILE, COLS, ROWS } from './config.js';
import { coneOutline } from './vision.js';
import { GUARD_HALF_ANGLE } from './guards.js';
import { CAMERA_HALF_ANGLE } from './cameras.js';
import { drawHud } from './hud.js';
import { PHASE_TITLE, PHASE_CAUGHT, PHASE_CLEAR, PHASE_WIN } from './world.js';

const FLOOR_A = '#141b28';
const FLOOR_B = '#16202f';
const WALL = '#2c3a52';
const CRATE = '#5a4632';
const SHADOW = 'rgba(4, 6, 12, 0.72)';

function drawRoom(ctx, world) {
  for (let gy = 0; gy < ROWS; gy += 1) {
    for (let gx = 0; gx < COLS; gx += 1) {
      ctx.fillStyle = (gx + gy) % 2 === 0 ? FLOOR_A : FLOOR_B;
      ctx.fillRect(gx * TILE, gy * TILE, TILE, TILE);
      if (world.solids[gy][gx]) {
        ctx.fillStyle = world.crateAt[gy][gx] ? CRATE : WALL;
        ctx.fillRect(gx * TILE, gy * TILE, TILE, TILE);
        ctx.strokeStyle = 'rgba(0,0,0,0.35)';
        ctx.strokeRect(gx * TILE + 1.5, gy * TILE + 1.5, TILE - 3, TILE - 3);
        if (world.crateAt[gy][gx]) {
          ctx.strokeStyle = 'rgba(0,0,0,0.3)';
          ctx.beginPath();
          ctx.moveTo(gx * TILE + 4, gy * TILE + 4);
          ctx.lineTo(gx * TILE + TILE - 4, gy * TILE + TILE - 4);
          ctx.moveTo(gx * TILE + TILE - 4, gy * TILE + 4);
          ctx.lineTo(gx * TILE + 4, gy * TILE + TILE - 4);
          ctx.stroke();
        }
      }
    }
  }
  for (const s of world.shadows) {
    ctx.fillStyle = SHADOW;
    ctx.fillRect(s.x, s.y, TILE, TILE);
  }
}

function drawLoot(ctx, world) {
  // Exit: pulsing green doorway, lit green once every loot is carried.
  const e = world.exit;
  const ready = world.lootTaken >= world.lootTotal;
  const pulse = 0.5 + 0.5 * Math.sin(world.seconds * 5);
  ctx.fillStyle = ready ? `rgba(92, 219, 96, ${0.35 + 0.3 * pulse})` : 'rgba(92,219,96,0.15)';
  ctx.fillRect(e.gx * TILE, e.gy * TILE, TILE, TILE);
  ctx.strokeStyle = ready ? '#5cdb60' : 'rgba(92,219,96,0.5)';
  ctx.lineWidth = 2;
  ctx.strokeRect(e.gx * TILE + 2, e.gy * TILE + 2, TILE - 4, TILE - 4);
  ctx.lineWidth = 1;
  ctx.fillStyle = ready ? '#c9f5cb' : '#7fae81';
  ctx.font = 'bold 11px system-ui, sans-serif';
  ctx.textAlign = 'center';
  ctx.fillText('EXIT', e.x, e.y + 4);

  // Gems: small blue diamonds that sparkle.
  for (const gem of world.gems) {
    if (gem.taken) continue;
    ctx.save();
    ctx.translate(gem.x, gem.y);
    ctx.rotate(world.seconds * 1.4 + gem.gx);
    ctx.fillStyle = '#4cc9f0';
    ctx.beginPath();
    ctx.moveTo(0, -9); ctx.lineTo(7, 0); ctx.lineTo(0, 9); ctx.lineTo(-7, 0);
    ctx.closePath();
    ctx.fill();
    ctx.strokeStyle = 'rgba(255,255,255,0.7)';
    ctx.stroke();
    ctx.restore();
  }

  // Vault: gold door with the prize behind it.
  const v = world.vault;
  if (v) {
    ctx.fillStyle = v.cracked ? '#6b5620' : '#c9a227';
    ctx.fillRect(v.gx * TILE + 4, v.gy * TILE + 4, TILE - 8, TILE - 8);
    ctx.strokeStyle = v.cracked ? '#3a3010' : '#ffe28a';
    ctx.lineWidth = 2;
    ctx.strokeRect(v.gx * TILE + 6, v.gy * TILE + 6, TILE - 12, TILE - 12);
    ctx.lineWidth = 1;
    ctx.fillStyle = v.cracked ? '#2c2610' : '#5c4a10';
    ctx.beginPath();
    ctx.arc(v.x, v.y, 6, 0, Math.PI * 2);
    ctx.fill();
    if (!v.cracked) {
      ctx.fillStyle = '#fff2c2';
      ctx.font = 'bold 10px system-ui, sans-serif';
      ctx.fillText('VAULT', v.x, v.y - TILE / 2 + 4);
    }
  }
}

function drawCones(ctx, world) {
  // Guard cones: amber when patrolling, red while hunting, red-tinted when actively seeing you.
  for (const guard of world.guards) {
    const pts = coneOutline(world, guard.x, guard.y, guard.facing, GUARD_HALF_ANGLE, 250);
    const hunting = guard.huntTimer > 0;
    const seeing = guard.fill > 0;
    ctx.beginPath();
    ctx.moveTo(pts[0][0], pts[0][1]);
    for (const [x, y] of pts.slice(1)) ctx.lineTo(x, y);
    ctx.closePath();
    ctx.fillStyle = seeing ? 'rgba(232, 72, 77, 0.30)'
      : hunting ? 'rgba(232, 72, 77, 0.18)' : 'rgba(244, 196, 60, 0.16)';
    ctx.fill();
    ctx.strokeStyle = seeing ? 'rgba(232,72,77,0.8)' : hunting ? 'rgba(232,72,77,0.5)' : 'rgba(244,196,60,0.45)';
    ctx.stroke();
  }
  // Camera cones: cool blue-white beams sweeping from a wall housing.
  for (const camera of world.cameras) {
    const pts = coneOutline(world, camera.x, camera.y, camera.facing, CAMERA_HALF_ANGLE, 210);
    ctx.beginPath();
    ctx.moveTo(pts[0][0], pts[0][1]);
    for (const [x, y] of pts.slice(1)) ctx.lineTo(x, y);
    ctx.closePath();
    ctx.fillStyle = 'rgba(120, 200, 255, 0.14)';
    ctx.fill();
    ctx.strokeStyle = 'rgba(120,200,255,0.45)';
    ctx.stroke();
    ctx.fillStyle = '#9fd8ff';
    ctx.beginPath();
    ctx.arc(camera.x, camera.y, 7, 0, Math.PI * 2);
    ctx.fill();
    ctx.strokeStyle = '#e6f4ff';
    ctx.beginPath();
    ctx.moveTo(camera.x, camera.y);
    ctx.lineTo(camera.x + Math.cos(camera.facing) * 12, camera.y + Math.sin(camera.facing) * 12);
    ctx.stroke();
  }
}

function drawActors(ctx, world) {
  // Sprint noise ring.
  if (world.noise) {
    const n = world.noise;
    ctx.beginPath();
    ctx.arc(n.x, n.y, NOISE_DRAW_RADIUS * (1 - n.t / 0.7), 0, Math.PI * 2);
    ctx.strokeStyle = 'rgba(244, 165, 60, 0.5)';
    ctx.lineWidth = 3;
    ctx.stroke();
    ctx.lineWidth = 1;
  }
  // Guards: dark figures with a bright visor facing where they look.
  for (const guard of world.guards) {
    const hunting = guard.huntTimer > 0;
    ctx.fillStyle = hunting ? '#7d2f33' : '#3a4a63';
    ctx.beginPath();
    ctx.arc(guard.x, guard.y, 13, 0, Math.PI * 2);
    ctx.fill();
    ctx.strokeStyle = hunting ? '#e8484d' : '#8fa4c2';
    ctx.stroke();
    ctx.strokeStyle = '#f4c43c';
    ctx.lineWidth = 3;
    ctx.beginPath();
    ctx.moveTo(guard.x, guard.y);
    ctx.lineTo(guard.x + Math.cos(guard.facing) * 14, guard.y + Math.sin(guard.facing) * 14);
    ctx.stroke();
    ctx.lineWidth = 1;
  }
  // The thief: teal, with a soft cap lamp so you always find yourself.
  const t = world.thief;
  ctx.fillStyle = 'rgba(20, 30, 45, 0.5)';
  ctx.beginPath();
  ctx.ellipse(t.x, t.y + 6, 12, 5, 0, 0, Math.PI * 2);
  ctx.fill();
  ctx.fillStyle = t.sneaking ? '#2aa79b' : '#37d4c4';
  ctx.beginPath();
  ctx.arc(t.x, t.y, 11, 0, Math.PI * 2);
  ctx.fill();
  ctx.strokeStyle = '#d8fff9';
  ctx.stroke();
  ctx.strokeStyle = '#d8fff9';
  ctx.beginPath();
  ctx.moveTo(t.x, t.y);
  ctx.lineTo(t.x + Math.cos(t.facing) * 13, t.y + Math.sin(t.facing) * 13);
  ctx.stroke();
}
const NOISE_DRAW_RADIUS = 190;

function overlay(ctx, title, lines, tint) {
  ctx.fillStyle = tint;
  ctx.fillRect(0, 0, VIEW_W, VIEW_H);
  ctx.textAlign = 'center';
  ctx.fillStyle = '#f2f6fb';
  ctx.font = 'bold 54px system-ui, sans-serif';
  ctx.fillText(title, VIEW_W / 2, VIEW_H / 2 - 40);
  ctx.font = '17px system-ui, sans-serif';
  ctx.fillStyle = '#b8c6d8';
  lines.forEach((line, i) => ctx.fillText(line, VIEW_W / 2, VIEW_H / 2 + 6 + i * 26));
}

export function render(ctx, world) {
  ctx.clearRect(0, 0, VIEW_W, VIEW_H);
  drawRoom(ctx, world);
  drawCones(ctx, world);
  drawLoot(ctx, world);
  drawActors(ctx, world);
  drawHud(ctx, world);

  if (world.phase === PHASE_TITLE) {
    overlay(ctx, 'COBALT VAULT', [
      'A top-down heist in three floors.',
      'WASD / arrows to move · hold Shift to sneak · Ctrl to sprint (loud!) · hold E to crack the vault',
      'Read the cones: amber guards and blue cameras fill the ALARM meter while they see you.',
      'Take every gem and the vault, then leave through the EXIT. Press Enter to begin the job.',
    ], 'rgba(5, 8, 15, 0.82)');
  } else if (world.phase === PHASE_CAUGHT) {
    overlay(ctx, 'CAUGHT', [
      world.statusLine,
      `Score kept: ${world.score} — you go back in in a moment (or press R now).`,
    ], 'rgba(60, 8, 10, 0.62)');
  } else if (world.phase === PHASE_CLEAR) {
    overlay(ctx, 'FLOOR CLEARED', [
      world.levelName,
      `Loot ${world.lootTaken}/${world.lootTotal} · score ${world.score}`,
      'Descending...',
    ], 'rgba(8, 40, 16, 0.55)');
  } else if (world.phase === PHASE_WIN) {
    overlay(ctx, 'CLEAN GETAWAY', [
      `The Cobalt Vault is emptied. Final score: ${world.score}.`,
      `Time: ${Math.floor(world.seconds / 60)}m ${Math.floor(world.seconds % 60)}s. Press Enter to run it again.`,
    ], 'rgba(6, 12, 24, 0.8)');
  }
}

// Cobalt Vault — entry point and game loop. Boots the canvas, scales the fixed internal view to
// the window, polls the keyboard each frame, advances the world one fixed 60 Hz step, renders,
// and handles the phase transitions the overlays promise: Enter starts the job, R retries the
// floor the moment you are caught, and Enter runs the whole vault again after the getaway.

import { VIEW_W, VIEW_H } from './config.js';
import { World, PHASE_TITLE, PHASE_CAUGHT, PHASE_WIN, PHASE_CLEAR, STEP } from './world.js';
import { render } from './render.js';
import { Input } from './input.js';
import { Sfx } from './audio.js';
import { stageShot } from './shots.js';

const canvas = document.getElementById('game');
canvas.width = VIEW_W;
canvas.height = VIEW_H;
const ctx = canvas.getContext('2d');
const world = new World();
const input = new Input();
const sfx = new Sfx();

// Letterbox: keep the 1280x800 view whole, centred, at whatever scale fits the window.
function fit() {
  const scale = Math.min(window.innerWidth / VIEW_W, window.innerHeight / VIEW_H);
  canvas.style.transform = `translate(-50%, -50%) scale(${scale})`;
  canvas.style.left = '50%';
  canvas.style.top = '50%';
  canvas.style.position = 'fixed';
}
window.addEventListener('resize', fit);
fit();

const query = new URLSearchParams(window.location.search);
const shotName = query.get('shot');
let shotStaged = false;

function startPressed(intent) {
  return intent.interact || intent.up || intent.down || intent.left || intent.right;
}

/** Advance one frame: play steps the world, the other phases only wait for the player. */
function frame() {
  const intent = input.poll();

  if (shotName && !shotStaged) {
    // Screenshot mode: stage the named scene once, then hold the frame steady for capture.
    stageShot(shotName, world);
    shotStaged = true;
  } else if (shotName) {
    render(ctx, world);
    return;
  }

  if (world.phase === PHASE_TITLE && startPressed(intent)) {
    world.phase = 'play';
    world.phaseTimer = 0;
    sfx.tone(523, 0.2, 'triangle', 0.08);
  } else if (world.phase === PHASE_CAUGHT && intent.restart) {
    world.retry();
  } else if (world.phase === PHASE_WIN && intent.restart) {
    world.reset(0, 0);
    world.phase = 'play';
  } else {
    const lootBefore = world.lootTaken;
    const wasPhase = world.phase;
    world.step(intent);
    if (world.lootTaken > lootBefore) sfx.gem();
    if (wasPhase !== world.phase) {
      if (world.phase === PHASE_CAUGHT) sfx.alarm();
      if (world.phase === PHASE_CLEAR) sfx.clear();
    }
  }
  render(ctx, world);
}

setInterval(frame, STEP * 1000);

